// CogBox - test of the Fabricator's install, update and uninstall (fabricator_install.cpp, also split as prepare /
// unpack on another thread / commit, with the game started or the mods folder changed in between) and of the zip unpacking they
// share with the Mods tab's "Add a mod (zip)" (mods.cpp mods_unpack_zip / mods_add_zip). The zips are made
// here with miniz from generated bytes, in a temporary folder with a non-ASCII name. game_def / game_root are stubbed
// below (the mods folder is the temporary one). Prints FAIL lines; exit code = failures. MinGW, from cogbox\:
//   SDL=<SDL3 mingw>/x86_64-w64-mingw32/include
//   gcc -w -c third_party/miniz/miniz.c -o miniz.o
//   g++ -std=c++17 -Wall -Wextra -DUNICODE -D_UNICODE -DWIN32_LEAN_AND_MEAN -DNOMINMAX -Ithird_party/imgui -I$SDL
//       -Ithird_party -Isrc -I../src/layer2_ue3/include -I../src/layer0_xenos/include -I../../Gears3-Native/src/layer2_ue3
//       test/fabricator_install_test.cpp src/fabricator_install.cpp src/mods.cpp src/fabricator_model.cpp src/mod_file_rules.cpp src/util.cpp
//       src/mod_conflicts.cpp src/mod_conflicts_scan.cpp   (mods_list asks for the mods' conflicts)
//       src/gears_settings.cpp src/i18n.cpp ../../Gears3-Native/src/layer2_ue3/modcore/modcore.cpp miniz.o
//       -static-libgcc -static-libstdc++ <SDL3 mingw>/x86_64-w64-mingw32/lib/libSDL3.dll.a -lshell32 -lole32 -luuid
//       -lbcrypt -ladvapi32 -o fabricator_install_test.exe   (SDL3.dll beside it: mods.cpp's texture-pack count uses SDL_GetTicks)
#include "../src/app.h"
#include "../src/fabricator_install.h"
#include "../src/fabricator_model.h"
#include "../src/mod_conflicts.h"
#include "../third_party/miniz/miniz.h"

#include <algorithm>
#include <chrono>
#include <cstdio>
#include <cstring>
#include <string>
#include <thread>
#include <utility>
#include <vector>

static int g_failures = 0;
#define CHECK(cond)                                                      \
    do {                                                                 \
        if (!(cond)) {                                                   \
            printf("FAIL %s:%d  %s\n", __FILE__, __LINE__, #cond);       \
            g_failures++;                                                \
        }                                                                \
    } while (0)

// ---- stubs: the games (games.cpp needs most of the launcher) ----
static std::string g_root;
const GameDef &game_def(int)
{
    static GameDef d = {};
    d.id = G_GEARS2; d.name = "Gears of War 2"; d.shortName = "Gears 2"; d.key = "gears2"; d.dir = "Gears2";
    return d;
}
std::string game_root(int) { return join(g_root, "Gears2"); }

// ---- helpers ----
static std::string make_zip(const std::vector<std::pair<std::string, std::string>> &files)
{
    mz_zip_archive z;
    memset(&z, 0, sizeof z);
    mz_zip_writer_init_heap(&z, 0, 0);
    for (const auto &f : files) mz_zip_writer_add_mem(&z, f.first.c_str(), f.second.data(), f.second.size(), MZ_BEST_COMPRESSION);
    void *buf = nullptr;
    size_t n = 0;
    mz_zip_writer_finalize_heap_archive(&z, &buf, &n);
    std::string out((const char *)buf, n);
    mz_zip_writer_end(&z);
    return out;
}
static std::string put_zip(const std::string &name, const std::vector<std::pair<std::string, std::string>> &files)
{
    std::string p = join(g_root, name);
    write_file(p, make_zip(files));
    return p;
}
static std::string text_of(const std::string &p)
{
    std::string s;
    return read_file(p, s) ? s : std::string("<missing>");
}
static bool exists(const std::string &p) { return GetFileAttributesW(widen(p).c_str()) != INVALID_FILE_ATTRIBUTES; }
static int index_of(const std::vector<ModItem> &v, const std::string &folder)
{
    for (size_t i = 0; i < v.size(); i++) if (v[i].folder == folder) return (int)i;
    return -1;
}
static void remove_tree(const std::wstring &dir)
{
    WIN32_FIND_DATAW fd;
    HANDLE f = FindFirstFileW((dir + L"\\*").c_str(), &fd);
    if (f != INVALID_HANDLE_VALUE) {
        do {
            std::wstring n = fd.cFileName;
            if (n == L"." || n == L"..") continue;
            std::wstring p = dir + L"\\" + n;
            if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) remove_tree(p); else DeleteFileW(p.c_str());
        } while (FindNextFileW(f, &fd));
        FindClose(f);
    }
    RemoveDirectoryW(dir.c_str());
}

int main()
{
    wchar_t tmp[MAX_PATH];
    GetTempPathW(MAX_PATH, tmp);
    g_root = join(narrow(tmp), "cogbox fab test \xC3\xA9\xC3\x9F\xE4\xB8\xAD");   // "...éß中"
    remove_tree(widen(g_root));
    make_dirs(join(g_root, "Gears2\\mods"));

    App a;
    a.ini.path = join(g_root, "CogBox.ini");
    const int g = G_GEARS2;
    const std::string mods = mods_dir(g), hb = join(mods, "Horde Bank"), bak = join(mods, ".fabricator-backup\\Horde Bank");

    // a mod the player added by hand, first in the order and on
    make_dirs(join(mods, "Other\\GearGame"));
    write_file(join(mods, "Other\\GearGame\\o.xxx"), "other");
    a.ini.set("Mods", "gears2Order", "Other");
    a.ini.set("Mods", "gears2Enabled", "Other");

    FabInstallItem item;   // a "file" install: its identity is the mod.ini Name
    item.name = "Horde Bank"; item.version = "1.0"; item.sha256 = "aa11";

    // ---- install ----
    {
        std::string z = put_zip("hb1.zip", {{"Horde Bank/mod.ini", "[Mod]\nName = Horde Bank\nGame = gears2\n"},
                                            {"Horde Bank/GearGame/CookedXenon/a.xxx", "v1"}});
        std::string err = fab_install(a, g, item, z);
        CHECK(err == "");
        CHECK(text_of(join(hb, "GearGame\\CookedXenon\\a.xxx")) == "v1");
        CHECK(exists(join(hb, "mod.ini")));
        CHECK(!exists(hb + ".partial"));
        auto r = fab_read_record(hb);
        CHECK(r && r->source.kind == "file" && r->name == "Horde Bank" && r->version == "1.0" && r->sha256 == "aa11");
        std::vector<ModItem> v = mods_list(a, g);
        CHECK(v.size() == 2);
        CHECK(index_of(v, "Horde Bank") == 1);   // last in the order
        CHECK(index_of(v, "Horde Bank") >= 0 && v[index_of(v, "Horde Bank")].enabled);
        CHECK(index_of(v, "Horde Bank") >= 0 && v[index_of(v, "Horde Bank")].fab && v[index_of(v, "Horde Bank")].fab_source == "file");
        CHECK(index_of(v, "Other") >= 0 && !v[index_of(v, "Other")].fab && v[index_of(v, "Other")].fab_source.empty());
    }
    // the player moves it first and turns it off: an update keeps that
    mods_move(a, g, "Horde Bank", -1);
    mods_set_enabled(a, g, "Horde Bank", false);

    // ---- update by name: 1.0 then 1.1 (both "file" installs of "Horde Bank") update the same folder ----
    {
        write_file(join(hb, "my notes.txt"), "mine");   // added by hand to the installed folder
        item.version = "1.1"; item.sha256 = "bb22";
        std::string z = put_zip("hb2.zip", {{"Horde Bank/GearGame/CookedXenon/a.xxx", "v2"},
                                            {"Horde Bank/GearGame/CookedXenon/b.xxx", "new"}});
        std::string err = fab_update(a, g, item, z);
        CHECK(err == "");
        CHECK(text_of(join(bak, "my notes.txt")) == "mine");
        CHECK(text_of(join(bak, "GearGame\\CookedXenon\\a.xxx")) == "v1");
        CHECK(text_of(join(hb, "GearGame\\CookedXenon\\a.xxx")) == "v2");
        CHECK(text_of(join(hb, "GearGame\\CookedXenon\\b.xxx")) == "new");
        CHECK(!exists(join(hb, "my notes.txt")));
        CHECK(!exists(hb + ".partial"));
        auto r = fab_read_record(hb);
        CHECK(r && r->name == "Horde Bank" && r->version == "1.1" && r->sha256 == "bb22");
        std::vector<ModItem> v = mods_list(a, g);
        CHECK(v.size() == 2);
        CHECK(index_of(v, "Horde Bank") == 0);   // the same position
        CHECK(index_of(v, "Horde Bank") >= 0 && !v[index_of(v, "Horde Bank")].enabled);   // the same on/off state
        CHECK(index_of(v, ".fabricator-backup") < 0);   // the Mods tab doesn't show the backup folder
        for (const ModItem &m : v) CHECK(m.folder[0] != '.');
    }
    // a second update replaces the older backup (one kept per mod)
    {
        item.name = "HORDE bank"; item.version = "1.2";   // the name without case: still the same install
        std::string z = put_zip("hb3.zip", {{"Horde Bank/GearGame/CookedXenon/a.xxx", "v3"}});
        CHECK(fab_update(a, g, item, z) == "");
        CHECK(text_of(join(bak, "GearGame\\CookedXenon\\a.xxx")) == "v2");
        CHECK(!exists(join(bak, "my notes.txt")));
        CHECK(text_of(join(hb, "GearGame\\CookedXenon\\a.xxx")) == "v3");
    }
    // a broken update leaves the installed version as it was
    {
        std::string z = join(g_root, "broken.zip");
        write_file(z, "not a zip");
        CHECK(fab_update(a, g, item, z) != "");
        CHECK(text_of(join(hb, "GearGame\\CookedXenon\\a.xxx")) == "v3");
        CHECK(text_of(join(bak, "GearGame\\CookedXenon\\a.xxx")) == "v2");
        CHECK(!exists(hb + ".partial"));
    }
    // a move that fails (a file in the installed folder held open) keeps the older backup, and the installed version
    {
        HANDLE held = CreateFileW(widen(join(hb, "GearGame\\CookedXenon\\a.xxx")).c_str(), GENERIC_READ, 0, nullptr, OPEN_EXISTING, 0, nullptr);
        CHECK(held != INVALID_HANDLE_VALUE);
        FabInstallItem v4 = item;
        v4.version = "1.3";
        std::string z = put_zip("hb4.zip", {{"Horde Bank/GearGame/CookedXenon/a.xxx", "v4"}});
        CHECK(fab_update(a, g, v4, z) != "");
        CHECK(text_of(join(bak, "GearGame\\CookedXenon\\a.xxx")) == "v2");   // the older backup is still there
        CHECK(!exists(join(join(mods, ".fabricator-backup"), "Horde Bank.old")));
        CHECK(!exists(hb + ".partial"));
        CHECK(fab_uninstall(a, g, "Horde Bank") != "");
        CHECK(text_of(join(bak, "GearGame\\CookedXenon\\a.xxx")) == "v2");
        CloseHandle(held);
        CHECK(text_of(join(hb, "GearGame\\CookedXenon\\a.xxx")) == "v3");
        auto r = fab_read_record(hb);
        CHECK(r && r->version == "1.2" && r->name == "HORDE bank");
        CHECK(index_of(mods_list(a, g), "Horde Bank") == 0);
    }
    // while the game runs, nothing is installed, updated, uninstalled or added
    {
        a.run.proc = GetCurrentProcess();
        FabInstallItem other;
        other.name = "Running Mod";
        std::string z = put_zip("run.zip", {{"Running Mod/GearGame/r.xxx", "r"}});
        CHECK(fab_install(a, g, other, z) == "Close the game first.");
        FabInstallItem v5 = item;
        v5.version = "1.5";
        std::string z5 = put_zip("hb5.zip", {{"Horde Bank/GearGame/CookedXenon/a.xxx", "v5"}});
        CHECK(fab_update(a, g, v5, z5) == "Close the game first.");
        CHECK(fab_uninstall(a, g, "Horde Bank") == "Close the game first.");
        std::string err;
        CHECK(!mods_add_zip(a, g, z, err));
        CHECK(err == "Close the game first.");
        a.run.proc = nullptr;
        CHECK(!exists(join(mods, "Running Mod")));
        CHECK(!exists(join(mods, "Running Mod.partial")));
        CHECK(text_of(join(hb, "GearGame\\CookedXenon\\a.xxx")) == "v3");
        CHECK(text_of(join(bak, "GearGame\\CookedXenon\\a.xxx")) == "v2");
        CHECK(mods_list(a, g).size() == 2);
    }
    // the hidden-name guard runs after the character rule: "!.hidden" is the visible folder "hidden"
    {
        FabInstallItem h;
        h.name = "!.hidden";
        std::string z = put_zip("hidden.zip", {{"GearGame/h.xxx", "h"}, {"readme.txt", "r"}});
        CHECK(fab_install(a, g, h, z) == "");
        CHECK(text_of(join(mods, "hidden\\GearGame\\h.xxx")) == "h");
        CHECK(index_of(mods_list(a, g), "hidden") >= 0);
        CHECK(fab_uninstall(a, g, "hidden") == "");
        CHECK(mods_list(a, g).size() == 2);
    }
    // "Foo.old"'s backup is not the temporary name of "Foo"'s: updating Foo leaves it alone
    {
        const std::string br = join(mods, ".fabricator-backup");
        FabInstallItem fo, f;
        fo.name = "Foo.old";
        f.name = "Foo";
        auto zip_of = [&](const char *tag) { return put_zip("foo.zip", {{"GearGame/a.xxx", tag}, {"readme.txt", "r"}}); };
        fo.version = "1"; CHECK(fab_install(a, g, fo, zip_of("fo1")) == "");
        fo.version = "2"; CHECK(fab_update(a, g, fo, zip_of("fo2")) == "");
        f.version = "1"; CHECK(fab_install(a, g, f, zip_of("f1")) == "");
        f.version = "2"; CHECK(fab_update(a, g, f, zip_of("f2")) == "");
        f.version = "3"; CHECK(fab_update(a, g, f, zip_of("f3")) == "");
        CHECK(text_of(join(br, "Foo.old\\GearGame\\a.xxx")) == "fo1");   // intact
        CHECK(text_of(join(br, "Foo\\GearGame\\a.xxx")) == "f2");
        CHECK(text_of(join(mods, "Foo.old\\GearGame\\a.xxx")) == "fo2");
        CHECK(text_of(join(mods, "Foo\\GearGame\\a.xxx")) == "f3");
        CHECK(!exists(join(br, ".old-Foo")));

        // a crash between putting the older backup aside and the move: .old-Foo and no Foo backup. The next update
        // puts it back as the backup first (seen here because the move then fails), then supersedes it normally.
        CHECK(MoveFileExW(widen(join(br, "Foo")).c_str(), widen(join(br, ".old-Foo")).c_str(), 0));
        HANDLE held = CreateFileW(widen(join(mods, "Foo\\GearGame\\a.xxx")).c_str(), GENERIC_READ, 0, nullptr, OPEN_EXISTING, 0, nullptr);
        CHECK(held != INVALID_HANDLE_VALUE);
        f.version = "4"; CHECK(fab_update(a, g, f, zip_of("f4")) != "");
        CloseHandle(held);
        CHECK(text_of(join(br, "Foo\\GearGame\\a.xxx")) == "f2");   // restored as the backup
        CHECK(!exists(join(br, ".old-Foo")));
        CHECK(MoveFileExW(widen(join(br, "Foo")).c_str(), widen(join(br, ".old-Foo")).c_str(), 0));
        CHECK(fab_update(a, g, f, zip_of("f4")) == "");
        CHECK(text_of(join(br, "Foo\\GearGame\\a.xxx")) == "f3");
        CHECK(text_of(join(mods, "Foo\\GearGame\\a.xxx")) == "f4");
        CHECK(!exists(join(br, ".old-Foo")));
        CHECK(text_of(join(br, "Foo.old\\GearGame\\a.xxx")) == "fo1");
        // audit F1: a .old-Foo COGBox didn't make (a record, no token of COGBox's) is never removed - refused
        make_dirs(join(br, ".old-Foo"));
        FabInstallRecord rec; rec.name = "Foo"; rec.version = "1";
        fab_write_record(join(br, ".old-Foo"), rec);
        write_file(join(br, ".old-Foo\\keep.txt"), "keep");
        CHECK(fab_uninstall(a, g, "Foo") != "");
        CHECK(text_of(join(br, ".old-Foo\\keep.txt")) == "keep");
        DeleteFileW(widen(join(br, ".old-Foo\\keep.txt")).c_str());
        // a crash after the move (both there): .old-Foo is the superseded backup, removed (a record and COGBox's token)
        CHECK(dir_claim(join(br, ".old-Foo")));
        CHECK(fab_uninstall(a, g, "Foo") == "");
        CHECK(text_of(join(br, "Foo\\GearGame\\a.xxx")) == "f4");
        CHECK(!exists(join(br, ".old-Foo")));
        CHECK(fab_uninstall(a, g, "Foo.old") == "");
        CHECK(mods_list(a, g).size() == 2);
    }

    // ---- the split install (I6): prepare on this thread, check + unpack on another, commit here ----
    {
        FabInstallItem sm;
        sm.name = "Split Mod"; sm.version = "1.0"; sm.sha256 = "cc33";
        const std::string sp = join(mods, "Split Mod");
        std::string z = put_zip("split1.zip", {{"Split Mod/GearGame/s.xxx", "s1"}, {"Split Mod/mod.ini", "[Mod]\nName = Split Mod\nGame = gears2\n"}});
        FabInstallPlan plan;
        CHECK(fab_install_prepare(a, g, sm, z, &plan) == "");
        CHECK(plan.folder == "Split Mod" && !plan.update && plan.g == g && plan.zip == z);
        CHECK(!exists(sp) && !exists(sp + ".partial"));   // prepare makes nothing
        const std::string iniBefore = text_of(a.ini.path);
        const size_t listBefore = mods_list(a, g).size();
        std::string unpackErr = "not run";
        std::thread worker([&] { unpackErr = fab_install_unpack(plan); });
        worker.join();
        if (!unpackErr.empty()) printf("  unpack: %s\n", unpackErr.c_str());
        CHECK(unpackErr == "");
        CHECK(text_of(join(sp + ".partial", "GearGame\\s.xxx")) == "s1");   // unpacked beside, with its record
        auto pr = fab_read_record(sp + ".partial");
        CHECK(pr && pr->name == "Split Mod" && pr->version == "1.0");
        CHECK(!exists(sp));
        CHECK(text_of(a.ini.path) == iniBefore);                           // the worker never touched CogBox.ini
        CHECK(mods_list(a, g).size() == listBefore);                       // nor the Mods tab's list
        // a game started meanwhile: the commit refuses and keeps the unpacked folder for later
        a.run.proc = GetCurrentProcess();
        CHECK(fab_install_commit(a, plan) == "Close the game first.");
        CHECK(exists(sp + ".partial") && !exists(sp));
        a.run.proc = nullptr;
        CHECK(fab_install_commit(a, plan) == "");
        CHECK(text_of(join(sp, "GearGame\\s.xxx")) == "s1");
        CHECK(!exists(sp + ".partial"));
        std::vector<ModItem> v = mods_list(a, g);
        CHECK(index_of(v, "Split Mod") == (int)v.size() - 1 && v.back().enabled && v.back().fab);

        // an update prepared, then the mod uninstalled before the commit: refused, the .partial removed, nothing moved
        sm.version = "1.1";
        std::string z2 = put_zip("split2.zip", {{"Split Mod/GearGame/s.xxx", "s2"}});
        FabInstallPlan up;
        CHECK(fab_install_prepare(a, g, sm, z2, &up) == "");
        CHECK(up.update && up.folder == "Split Mod");
        CHECK(fab_install_unpack(up) == "");
        CHECK(fab_uninstall(a, g, "Split Mod") == "");
        CHECK(fab_install_commit(a, up) != "");
        CHECK(!exists(sp) && !exists(sp + ".partial"));
        CHECK(text_of(join(join(mods, ".fabricator-backup\\Split Mod"), "GearGame\\s.xxx")) == "s1");

        // a new install prepared, then a hand-made folder of that name appears: refused, the hand-made one untouched
        FabInstallPlan again;
        CHECK(fab_install_prepare(a, g, sm, z2, &again) == "");
        CHECK(!again.update && again.folder == "Split Mod");
        CHECK(fab_install_unpack(again) == "");
        make_dirs(sp);
        write_file(join(sp, "mine.txt"), "hand");
        CHECK(fab_install_commit(a, again) != "");
        CHECK(text_of(join(sp, "mine.txt")) == "hand" && !exists(sp + ".partial"));
        remove_tree(widen(sp));

        // a bad zip fails in the unpack step, leaving no .partial; a cancelled plan's .partial is removed
        std::string bz = join(g_root, "split-bad.zip");
        write_file(bz, "not a zip");
        FabInstallPlan bad;
        CHECK(fab_install_prepare(a, g, sm, bz, &bad) == "");
        CHECK(fab_install_unpack(bad) != "");
        CHECK(!exists(sp + ".partial"));
        FabInstallPlan cancelled;
        CHECK(fab_install_prepare(a, g, sm, z2, &cancelled) == "");
        CHECK(fab_install_unpack(cancelled) == "" && exists(sp + ".partial"));
        fab_install_abandon(cancelled);
        CHECK(!exists(sp + ".partial") && !exists(sp));
        // the game running: prepare refuses at once
        a.run.proc = GetCurrentProcess();
        FabInstallPlan running;
        CHECK(fab_install_prepare(a, g, sm, z2, &running) == "Close the game first.");
        a.run.proc = nullptr;
        CHECK(mods_list(a, g).size() == 2);
    }

    // ---- program list: programs in a zip are left out of the install (with a note), the rest goes in ----
    {
        FabInstallItem tool;
        tool.name = "Tool Mod";
        std::string z = put_zip("tool.zip", {{"Tool Mod/GearGame/x.xxx", "x"}, {"Tool Mod/tools/run.asi", "MZ"},
                                             {"Tool Mod/x.dll", "MZ"}, {"Tool Mod/inner.zip", "PK"}, {"Tool Mod/readme.HTA ", "h"}});
        std::vector<std::string> left;
        CHECK(fab_install(a, g, tool, z, &left) == "");
        const std::string tm = join(mods, "Tool Mod");
        CHECK(text_of(join(tm, "GearGame\\x.xxx")) == "x");
        CHECK(!exists(join(tm, "tools\\run.asi")) && !exists(join(tm, "x.dll")) && !exists(join(tm, "inner.zip")));
        CHECK(!exists(join(tm, "readme.HTA")));
        CHECK(left.size() == 4);
        CHECK(std::find(left.begin(), left.end(), "tools\\run.asi") != left.end());
        CHECK(std::find(left.begin(), left.end(), "x.dll") != left.end());
        CHECK(fab_uninstall(a, g, "Tool Mod") == "");
        CHECK(mods_list(a, g).size() == 2);
    }

    // ---- uninstall ----
    {
        CHECK(fab_uninstall(a, g, "Nope") != "");    // not there: nothing moved
        CHECK(fab_uninstall(a, g, "Other") != "");   // no record (added by hand): never moved
        CHECK(fab_uninstall(a, g, ".fabricator-backup") != "");
        CHECK(fab_uninstall(a, g, "..\\Gears2") != "");
        CHECK(exists(join(mods, "Other\\GearGame\\o.xxx")));
        CHECK(fab_uninstall(a, g, "Horde Bank") == "");
        CHECK(!exists(hb));
        CHECK(text_of(join(bak, "GearGame\\CookedXenon\\a.xxx")) == "v3");
        auto r = fab_read_record(bak);
        CHECK(r && r->source.kind == "file" && r->name == "HORDE bank");
        std::vector<ModItem> v = mods_list(a, g);
        CHECK(v.size() == 1 && index_of(v, "Other") == 0);
        CHECK(a.ini.get("Mods", "gears2Order").find("Horde Bank") == std::string::npos);
        CHECK(exists(join(mods, "Other\\GearGame\\o.xxx")));   // the hand-added mod is untouched
    }

    // ---- zip carries fabricator.json: never taken from a zip, the record on disk is COGBox's ----
    {
        const std::string fake = R"({"source":{"kind":"nexus","game_domain":"gearsofwar2","mod_id":7,"file_id":3},"name":"Someone Else","version":"9"})";
        std::string z = put_zip("carrier.zip", {{"Horde Bank/fabricator.json", fake}, {"Horde Bank/sub/FABRICATOR.JSON. ", fake},
                                                {"Horde Bank/GearGame/c.xxx", "c"}});
        FabInstallItem hbi;
        hbi.name = "Horde Bank"; hbi.version = "2.0";
        CHECK(fab_install(a, g, hbi, z) == "");
        auto r = fab_read_record(hb);
        CHECK(r && r->source.kind == "file" && r->name == "Horde Bank" && r->version == "2.0" && r->source.mod_id == 0);
        CHECK(text_of(join(hb, "GearGame\\c.xxx")) == "c");
        CHECK(!exists(join(hb, "sub\\FABRICATOR.JSON")));
        CHECK(fab_uninstall(a, g, "Horde Bank") == "");
        // added by hand through the Mods tab: no fabricator.json at all, so not an install of anything
        std::string err;
        std::string z2 = put_zip("carrier2.zip", {{"Carrier/fabricator.json", fake}, {"Carrier/GearGame/c.xxx", "c"}});
        CHECK(mods_add_zip(a, g, z2, err) && err == "");
        CHECK(!exists(join(mods, "Carrier\\fabricator.json")));
        CHECK(text_of(join(mods, "Carrier\\GearGame\\c.xxx")) == "c");
        std::vector<ModItem> v = mods_list(a, g);
        CHECK(index_of(v, "Carrier") >= 0 && !v[index_of(v, "Carrier")].fab);
        CHECK(fab_uninstall(a, g, "Carrier") != "" && exists(join(mods, "Carrier")));
        remove_tree(widen(join(mods, "Carrier")));
        mods_store(a, g, mods_list(a, g));
    }

    // ---- same name, hand-made folder: mods\Horde Bank without a record stays as it is ----
    {
        make_dirs(join(hb, "GearGame"));
        write_file(join(hb, "GearGame\\mine.xxx"), "hand");
        write_file(join(hb, "mod.ini"), "[Mod]\nName = Horde Bank\n");
        FabInstallItem hbi;
        hbi.name = "Horde Bank"; hbi.version = "3.0";
        std::string z = put_zip("hb-new.zip", {{"Horde Bank/GearGame/nw.xxx", "new"}});
        CHECK(fab_install(a, g, hbi, z) == "");
        const std::string fb = join(mods, "Horde Bank (Fabricator)");
        CHECK(text_of(join(fb, "GearGame\\nw.xxx")) == "new");
        auto r = fab_read_record(fb);
        CHECK(r && r->name == "Horde Bank" && r->version == "3.0");
        CHECK(text_of(join(hb, "GearGame\\mine.xxx")) == "hand");   // the first folder's files are unchanged
        CHECK(text_of(join(hb, "mod.ini")) == "[Mod]\nName = Horde Bank\n");
        CHECK(!exists(join(hb, "GearGame\\nw.xxx")) &&!exists(join(hb, "fabricator.json")));
        // and an update finds the Fabricator's folder, not the hand-made one
        hbi.version = "3.1";
        std::string z2 = put_zip("hb-new2.zip", {{"Horde Bank/GearGame/nw.xxx", "newer"}});
        CHECK(fab_install(a, g, hbi, z2) == "");
        CHECK(text_of(join(fb, "GearGame\\nw.xxx")) == "newer");
        CHECK(text_of(join(hb, "GearGame\\mine.xxx")) == "hand");
        CHECK(!exists(join(mods, "Horde Bank (Fabricator 2)")));
        CHECK(fab_uninstall(a, g, "Horde Bank (Fabricator)") == "");
        CHECK(fab_uninstall(a, g, "Horde Bank") != "");   // the hand-made one: never moved
        CHECK(text_of(join(hb, "GearGame\\mine.xxx")) == "hand");
        remove_tree(widen(hb));
        mods_store(a, g, mods_list(a, g));
        CHECK(mods_list(a, g).size() == 1);
    }

    // ---- the Mods tab's own "add a zip" still works (and shares the unpacking) ----
    {
        std::string z = put_zip("pack.zip", {{"Pack/GearGame/x.xxx", "px"}, {"Pack/y.dll", "MZ"}, {"Pack/tools/run.asi", "MZ"}});
        std::string err;
        std::vector<std::string> left;
        CHECK(mods_add_zip(a, g, z, err, &left));
        CHECK(left.size() == 2);   // the programs left out are reported
        CHECK(std::find(left.begin(), left.end(), "tools\\run.asi") != left.end());
        CHECK(std::find(left.begin(), left.end(), "y.dll") != left.end());
        CHECK(err == "");
        CHECK(text_of(join(mods, "Pack\\GearGame\\x.xxx")) == "px");
        CHECK(!exists(join(mods, "Pack\\y.dll")));   // programs are left out
        CHECK(!exists(join(mods, "Pack\\tools\\run.asi")));
        std::vector<ModItem> v = mods_list(a, g);
        CHECK(index_of(v, "Pack") == (int)v.size() - 1 && v.back().enabled);
    }

    // ---- final review: the startup sweep, the record before the unpack, a folder add's top folder, the Mods tab's
    // .partial name, '.'-named mod folders ----
    {
        FabInstallRecord rec;
        rec.name = "Gone";
        const std::string recorded = join(mods, "Gone.partial"), handOwn = join(mods, "Hand.partial");
        make_dirs(join(recorded, "GearGame"));
        write_file(join(recorded, "GearGame/half.xxx"), "half");
        CHECK(fab_write_record(recorded, rec));
        make_dirs(handOwn);
        write_file(join(handOwn, "x.xxx"), "x");
        // audit F1: a .partial with a record but no token of COGBox's (a forged one) is left alone
        const std::string forged = join(mods, "Forged.partial");
        make_dirs(forged);
        write_file(join(forged, "y.xxx"), "y");
        CHECK(fab_write_record(forged, rec));
        CHECK(dir_claim(recorded));
        fab_sweep_partials(g);
        CHECK(!exists(recorded));                 // COGBox's unfinished install: removed
        CHECK(text_of(join(handOwn, "x.xxx")) == "x");   // not COGBox's: left alone
        CHECK(text_of(join(forged, "y.xxx")) == "y");    // a record alone doesn't make it COGBox's
        remove_tree(widen(handOwn));
        remove_tree(widen(forged));

        // the record is written before the unpack: a failed unpack leaves nothing; a finished one has it
        FabInstallItem ti;
        ti.name = "Top Kept"; ti.version = "1";
        std::string z = put_zip("topkept.zip", {{"Top Kept/GearGame/t.xxx", "t"}});
        FabInstallPlan plan;
        CHECK(fab_install_prepare(a, g, ti, z, &plan) == "");
        plan.strip_top = false;   // a folder add: the zip's top folder is part of the mod
        CHECK(fab_install_unpack(plan) == "");
        CHECK(text_of(join(mods, "Top Kept.partial/Top Kept/GearGame/t.xxx")) == "t");
        CHECK(fab_read_record(join(mods, "Top Kept.partial")).has_value());
        // the Mods tab's add of a zip of that name keeps the Fabricator's .partial and unpacks beside it
        std::string z2 = put_zip("Top Kept.zip", {{"GearGame/m.xxx", "m"}, {"readme.txt", "r"}});   // (no single top folder: named by the zip)
        std::string err;
        CHECK(mods_add_zip(a, g, z2, err) && err.empty());
        CHECK(text_of(join(mods, "Top Kept/GearGame/m.xxx")) == "m");
        CHECK(text_of(join(mods, "Top Kept.partial/Top Kept/GearGame/t.xxx")) == "t");
        CHECK(fab_install_commit(a, plan) != "");   // the folder is the Mods tab's now: refused, .partial removed
        CHECK(!exists(join(mods, "Top Kept.partial")));
        FabInstallPlan bad = plan;
        bad.zip = join(g_root, "missing.zip");
        CHECK(fab_install_unpack(bad) != "" && !exists(join(mods, "Top Kept.partial")));
        remove_tree(widen(join(mods, "Top Kept")));

        // '.'-named folders are listed again, except the Fabricator's backups and unfinished unpackings
        make_dirs(join(mods, ".dotmod/GearGame"));
        std::vector<ModItem> v = mods_list(a, g);
        CHECK(index_of(v, ".dotmod") >= 0);
        CHECK(index_of(v, ".fabricator-backup") < 0);
        remove_tree(widen(join(mods, ".dotmod")));
        mods_store(a, g, mods_list(a, g));
    }

    // ---- mods_unpack_zip: names as Windows reads them, never outside the folder, real byte counts ----
    {
        std::string dest = join(g_root, "unpack1");
        make_dirs(dest);
        std::string err;
        std::string z = put_zip("names.zip", {{"Top/dir. /file.txt. ", "f"}, {"Top/GearGame/z.xxx", "z"}});
        CHECK(mods_unpack_zip(a, g, z, dest, true, err));
        CHECK(text_of(join(dest, "dir\\file.txt")) == "f");
        CHECK(text_of(join(dest, "GearGame\\z.xxx")) == "z");
        // fabricator.json at any depth (a file, or a folder of that name) is COGBox's own: never unpacked
        std::string dj = join(g_root, "unpack-fj");
        std::vector<std::string> left;
        z = put_zip("fj.zip", {{"Top/fabricator.json/x.bin", "d"}, {"Top/a/b/Fabricator.Json", "f"}, {"Top/keep.txt", "k"}});
        CHECK(mods_unpack_zip_in("", z, dj, true, err, &left));
        CHECK(text_of(join(dj, "keep.txt")) == "k");
        // Windows device names (the same rule as fab_check_zip) are never written
        std::string dd = join(g_root, "unpack-dev");
        z = put_zip("dev.zip", {{"Top/CONIN$.txt", "d"}, {"Top/sub/COM\xC2\xB9.dat", "d"}, {"Top/aux/x.bin", "d"}, {"Top/ok.txt", "k"}});
        CHECK(mods_unpack_zip_in("", z, dd, true, err));
        CHECK(text_of(join(dd, "ok.txt")) == "k");
        CHECK(!exists(join(dd, "sub\\COM\xC2\xB9.dat")) && !exists(join(dd, "aux")));
        CHECK(!exists(join(dj, "fabricator.json")) && !exists(join(dj, "a\\b\\Fabricator.Json")));
        CHECK(left.empty());   // not a program: left out without a note

        std::string dest2 = join(g_root, "unpack2");
        make_dirs(dest2);
        for (const char *bad : {"../evil.txt", "a/../../evil.txt", "a/.. /evil.txt", "C:evil.txt", "a/b:stream"}) {
            std::string z2 = put_zip("evil.zip", {{"a/ok.txt", "ok"}, {bad, "evil"}});
            err.clear();
            CHECK(!mods_unpack_zip(a, g, z2, dest2, false, err));
            CHECK(err != "");
        }
        CHECK(!exists(join(g_root, "evil.txt")));

        // the declared size lies (central directory says 10 bytes, the entry inflates to 100 000): refused
        std::string big(100000, 'q');
        std::string zz = make_zip({{"liar.bin", big}});
        for (size_t i = 0; i + 46 <= zz.size(); i++) {
            if (memcmp(zz.data() + i, "PK\x01\x02", 4) == 0) { uint32_t ten = 10; memcpy(&zz[i + 24], &ten, 4); }
            if (memcmp(zz.data() + i, "PK\x03\x04", 4) == 0) { uint32_t ten = 10; memcpy(&zz[i + 22], &ten, 4); }
        }
        std::string zp = join(g_root, "liar.zip");
        write_file(zp, zz);
        std::string dest3 = join(g_root, "unpack3");
        make_dirs(dest3);
        err.clear();
        CHECK(!mods_unpack_zip(a, g, zp, dest3, false, err));
        CHECK(!exists(join(dest3, "liar.bin")));   // the half-written entry is not left
    }

    // ---- mods the game leaves out (review of the conflicts): mod.ini enabled = false, another game's - a problem line
    // (Gears 2 runs modcore's mod.ini rules too), and their files are not counted against the mods that are used ----
    {
        for (const char *n : { "Left Out", "Kept", "Wrong Game" }) make_dirs(join(mods, std::string(n) + "\\GearGame\\CookedXenon"));
        write_file(join(mods, "Left Out\\mod.ini"), "[Mod]\nName = Left Out\nGame = gears2\nenabled = false\n");
        write_file(join(mods, "Wrong Game\\mod.ini"), "[Mod]\nName = Wrong Game\nGame = gears3\n");
        write_file(join(mods, "Kept\\mod.ini"), "[Mod]\nName = Kept\nGame = gears2\n");
        for (const char *n : { "Left Out", "Kept", "Wrong Game" }) write_file(join(mods, std::string(n) + "\\GearGame\\CookedXenon\\Shared.xxx"), n);
        a.ini.set("Mods", "gears2Order", "Left Out|Wrong Game|Kept");
        a.ini.set("Mods", "gears2Enabled", "Left Out|Wrong Game|Kept");
        std::vector<ModItem> v = mods_list(a, g);
        const int lo = index_of(v, "Left Out"), wg = index_of(v, "Wrong Game"), kp = index_of(v, "Kept");
        CHECK(lo >= 0 && v[lo].problem.find("enabled = false") != std::string::npos);
        CHECK(wg >= 0 && v[wg].problem.find("made for") != std::string::npos);
        CHECK(kp >= 0 && v[kp].problem.empty());
        // the worker's result (a few seconds at most): Kept shares Shared.xxx with both, but neither is used
        std::shared_ptr<const ModConflictSet> cs;
        for (int t = 0; t < 300 && !cs; t++) { cs = mod_conflicts_get(g); if (!cs) std::this_thread::sleep_for(std::chrono::milliseconds(10)); }
        CHECK(cs != nullptr);
        const ModConflicts *c = cs ? cs->find("Kept") : nullptr;
        CHECK(c != nullptr && c->replaces.empty() && c->replaced_by.empty());
        // and with the mod.ini switch on again, the same file is a conflict Kept wins
        write_file(join(mods, "Left Out\\mod.ini"), "[Mod]\nName = Left Out\nGame = gears2\n");
        v = mods_list(a, g);
        CHECK(index_of(v, "Left Out") >= 0 && v[index_of(v, "Left Out")].problem.empty());
        cs.reset();
        for (int t = 0; t < 300; t++) {
            cs = mod_conflicts_get(g);
            c = cs ? cs->find("Kept") : nullptr;
            if (c && !c->replaces.empty()) break;
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
        CHECK(c != nullptr && c->replaces.size() == 1 && c->replaces[0].other_name == "Left Out" && c->replaces[0].count == 1);
        mod_conflicts_shutdown();
    }

    remove_tree(widen(g_root));
    printf("%d failure(s)\n", g_failures);
    return g_failures;
}
